describe('Duplicate Record Functionality', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully duplicate an existing record with one click', () => {
    // Verify initial state: no records displayed
    cy.get('[data-testid="no-records-message"]').should('be.visible');

    // Intercept API call to fetch records
    cy.intercept('GET', '/api/records').as('getRecords');
    cy.wait('@getRecords');

    // Verify one record is displayed
    cy.get('[data-testid="record-list"]').should('be.visible');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 0);

    // Click on the first record to duplicate
    cy.get('[data-testid="record-item"]').first().click();

    // Verify duplicate button appears
    cy.get('[data-testid="duplicate-button"]').should('be.visible');

    // Click duplicate button
    cy.get('[data-testid="duplicate-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Record successfully duplicated');

    // Verify duplicate record is now visible
    cy.get('[data-testid="record-item"]').should('have.length', 2);

    // Verify duplicate record has unique ID
    cy.get('[data-testid="record-item"]').eq(1).should('have.attr', 'data-record-id');
    cy.get('[data-testid="record-item"]').eq(1).should('have.attr', 'data-record-id').and('not.equal', cy.get('[data-testid="record-item"]').first().attr('data-record-id'));

    // Verify duplicate record has same data as original
    cy.get('[data-testid="record-item"]').eq(1).should('have.text', 'Original Record');
  });

